/* ── CANVAS CURSOR ── */
function Cursor() {
  const canvasRef = useRef(null);
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    const resize = () => { canvas.width = window.innerWidth; canvas.height = window.innerHeight; };
    resize();
    window.addEventListener("resize", resize);
    const mouse = { x: -200, y: -200 };
    const ring  = { x: -200, y: -200 };
    let isHov = false, isClick = false, raf;
    const onMove = (e) => {
      mouse.x = e.clientX; mouse.y = e.clientY;
      isHov = !!e.target.closest("a,button,textarea,input,select,[role='button']");
    };
    const onDown = () => { isClick = true; };
    const onUp   = () => { isClick = false; };
    const draw = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ring.x += (mouse.x - ring.x) * 0.13;
      ring.y += (mouse.y - ring.y) * 0.13;
      const spotR = isHov ? 160 : 300;
      const spotA = isHov ? 0.13 : 0.07;
      const grd = ctx.createRadialGradient(mouse.x, mouse.y, 0, mouse.x, mouse.y, spotR);
      grd.addColorStop(0,   `rgba(139,92,246,${spotA})`);
      grd.addColorStop(0.5, `rgba(139,92,246,${spotA * 0.4})`);
      grd.addColorStop(1,   "rgba(139,92,246,0)");
      ctx.fillStyle = grd;
      ctx.beginPath(); ctx.arc(mouse.x, mouse.y, spotR, 0, Math.PI * 2); ctx.fill();
      const ringR = isHov ? 20 : isClick ? 10 : 14;
      ctx.beginPath(); ctx.arc(ring.x, ring.y, ringR, 0, Math.PI * 2);
      ctx.strokeStyle = isHov ? "rgba(168,85,247,1)" : "rgba(168,85,247,0.65)";
      ctx.lineWidth = isHov ? 1.5 : 1; ctx.stroke();
      if (isHov) {
        ctx.beginPath(); ctx.arc(ring.x, ring.y, ringR + 4, 0, Math.PI * 2);
        ctx.strokeStyle = "rgba(168,85,247,0.15)"; ctx.lineWidth = 6; ctx.stroke();
      }
      const dotR = isClick ? 2.5 : 3.5;
      ctx.beginPath(); ctx.arc(mouse.x, mouse.y, dotR, 0, Math.PI * 2);
      ctx.fillStyle = "#a855f7"; ctx.shadowColor = "#a855f7"; ctx.shadowBlur = 8;
      ctx.fill(); ctx.shadowBlur = 0;
      raf = requestAnimationFrame(draw);
    };
    window.addEventListener("mousemove", onMove);
    window.addEventListener("mousedown", onDown);
    window.addEventListener("mouseup",   onUp);
    raf = requestAnimationFrame(draw);
    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener("resize",    resize);
      window.removeEventListener("mousemove", onMove);
      window.removeEventListener("mousedown", onDown);
      window.removeEventListener("mouseup",   onUp);
    };
  }, []);
  return <canvas ref={canvasRef} style={{ position:"fixed", top:0, left:0, width:"100vw", height:"100vh", pointerEvents:"none", zIndex:99999 }} />;
}

/* ── TYPEWRITER ── */
function TypeWriter({ words }) {
  const [txt, setTxt] = useState("");
  const [wi,  setWi]  = useState(0);
  const [ci,  setCi]  = useState(0);
  const [del, setDel] = useState(false);
  useEffect(() => {
    const w = words[wi];
    const t = setTimeout(() => {
      if (!del && ci < w.length)        { setTxt(w.slice(0,ci+1)); setCi(c=>c+1); }
      else if (!del && ci===w.length)   { setTimeout(()=>setDel(true),1600); }
      else if (del && ci > 0)           { setTxt(w.slice(0,ci-1)); setCi(c=>c-1); }
      else                              { setDel(false); setWi(w=>(w+1)%words.length); }
    }, del ? 45 : 85);
    return () => clearTimeout(t);
  }, [ci, del, wi, words]);
  return <span style={{ color:"#94a3b8" }}>{txt}<span style={{ animation:"blink 1s infinite", color:"#a855f7" }}>|</span></span>;
}

/* ── SKILL BAR ── */
function SkillBar({ s }) {
  const [w, setW] = useState(0);
  const ref = useRef(null);
  useEffect(() => {
    const obs = new IntersectionObserver(([e]) => {
      if (e.isIntersecting) { setTimeout(()=>setW(s.level),100); obs.disconnect(); }
    }, { threshold:0.2 });
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, [s.level]);
  return (
    <div ref={ref} className="scard" style={{ padding:"16px 20px", background:"#0f0f1a", border:"1px solid #212136", borderRadius:12, transition:"border-color .22s,background .22s" }}>
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:10 }}>
        <div style={{ display:"flex", alignItems:"center", gap:8 }}>
          <span style={{ fontSize:17 }}>{s.icon}</span>
          <span style={{ fontSize:13, fontWeight:500, color:"#e2e8f0" }}>{s.name}</span>
        </div>
        <span style={{ fontFamily:"'JetBrains Mono',monospace", fontSize:11, color:"#4b5563" }}>{s.level}%</span>
      </div>
      <div style={{ height:3, background:"#1e1e32", borderRadius:3, overflow:"hidden" }}>
        <div style={{ height:"100%", width:`${w}%`, background:"linear-gradient(90deg,#6d28d9,#a855f7)", borderRadius:3, transition:"width 1.5s cubic-bezier(.4,0,.2,1)" }} />
      </div>
    </div>
  );
}

/* ── CLOCK ── */
function Clock() {
  const [t, setT] = useState(new Date());
  useEffect(() => { const i = setInterval(()=>setT(new Date()),1000); return ()=>clearInterval(i); }, []);
  const h = t.getHours().toString().padStart(2,"0");
  const m = t.getMinutes().toString().padStart(2,"0");
  const s = t.getSeconds().toString().padStart(2,"0");
  return <span>{h}<span style={{opacity:.35}}>:</span>{m}<span style={{opacity:.35}}>:</span>{s}</span>;
}

